const raw = $input.item.json;
const content = typeof raw.content === 'string' ? raw.content : JSON.stringify(raw.content);
const msg = JSON.parse(content.trim());
const date = msg.date;
const parts = date.split('-');
const year = parts[0];
const month = parts[1];
const day = parts[2];
const records = msg.records;

return records.map(function(r) {
  return {
    json: {
      date: date,
      year: year,
      month: month,
      day: day,
      hour: r.hour,
      hourStr: String(r.hour).padStart(2, '0'),
      time: r.time,
      latitude: Number(r.latitude),
      longitude: Number(r.longitude),
      temperature_2m: r.temperature_2m,
      temperature_2m_unit: r.temperature_2m_unit,
      precipitation: r.precipitation,
      precipitation_unit: r.precipitation_unit,
      ozone: r.ozone,
      ozone_unit: r.ozone_unit,
      carbon_dioxide: r.carbon_dioxide,
      carbon_dioxide_unit: r.carbon_dioxide_unit
    }
  };
});

const r = $input.item.json;
const dateCompact = r.date.replace(/-/g, '');
const hourStr = r.hourStr;
const fileName = hourStr + '_' + dateCompact + '.csv';
const path = 'clean/environment_clean/' + r.year + '/' + r.month + '/' + r.day + '/' + fileName;

const fields = ['date','year','month','day','hour','time','latitude','longitude','temperature_2m','temperature_2m_unit','precipitation','precipitation_unit','ozone','ozone_unit','carbon_dioxide','carbon_dioxide_unit'];

const header = fields.join(',');
const row = fields.map(function(f) { return r[f] !== undefined && r[f] !== null ? r[f] : ''; }).join(',');
const csvContent = header + '\n' + row;

return {
  json: { date: r.date, year: r.year, month: r.month, day: r.day, hourStr: hourStr, path: path, fileName: fileName },
  binary: {
    data: {
      data: Buffer.from(csvContent).toString('base64'),
      mimeType: 'text/csv',
      fileName: fileName
    }
  }
};

const r = $input.item.json;
const dateCompact = r.date.replace(/-/g, '');
const hourStr = r.hourStr;
const fileName = hourStr + '_' + dateCompact + '.csv';
const path = 'processed/environment_observations_long/' + r.year + '/' + r.month + '/' + r.day + '/' + fileName;

const variables = [
  { variable: 'temperature_2m', unit: r.temperature_2m_unit, value: r.temperature_2m, dataset: 'historical_weather' },
  { variable: 'precipitation', unit: r.precipitation_unit, value: r.precipitation, dataset: 'historical_weather' },
  { variable: 'ozone', unit: r.ozone_unit, value: r.ozone, dataset: 'air_quality' },
  { variable: 'carbon_dioxide', unit: r.carbon_dioxide_unit, value: r.carbon_dioxide, dataset: 'air_quality' }
];

const header = 'source,dataset,date,year,month,day,hour,time,latitude,longitude,variable,value,unit';
const rows = variables.map(function(v) {
  const val = v.value !== undefined && v.value !== null ? v.value : '';
  return 'open_meteo,' + v.dataset + ',' + r.date + ',' + r.year + ',' + r.month + ',' + r.day + ',' + hourStr + ',' + r.time + ',' + r.latitude + ',' + r.longitude + ',' + v.variable + ',' + val + ',' + v.unit;
});
const csvContent = header + '\n' + rows.join('\n');

return {
  json: { date: r.date, year: r.year, month: r.month, day: r.day, hourStr: hourStr, path: path, fileName: fileName },
  binary: {
    data: {
      data: Buffer.from(csvContent).toString('base64'),
      mimeType: 'text/csv',
      fileName: fileName
    }
  }
};
